arguments.new_str:
class SyncJob
{
    void Run(BlogContext context)
    {
        // Breaking change 5: EF 9 no longer uses "Discriminator" in queries —
        // it uses "$type". Any raw SQL referencing c.Discriminator must be updated
        // UNLESS HasJsonPropertyName("Discriminator") is configured (which we did).
        // If you have raw SQL elsewhere, use: WHERE c["Discriminator"] = 'Blog'

        var blogs = context.Blogs.ToList();
        foreach (var b in blogs) { b.Name = b.Name.Trim(); }
        context.SaveChanges();
    }
}

