using Microsoft.EntityFrameworkCore;

class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Blog>(entity =>
        {
            // BREAKING CHANGE 1 — Discriminator property renamed.
            // EF 9 writes "$type" instead of "Discriminator".
            // Existing documents use "Discriminator", so pin the old name.
            entity.HasDiscriminator().HasJsonPropertyName("Discriminator");

            // BREAKING CHANGE 2 — id value format changed.
            // EF 8 synthesized id as "Blog|<key>"; EF 9 uses just "<key>".
            // Existing documents have "Blog|1" etc.  Pin the old format with
            // a value converter so EF can still find them.
            entity.Property(b => b.Id)
                  .HasConversion(
                      key => $"Blog|{key}",
                      id  => id.StartsWith("Blog|") ? id.Substring(5) : id);

            // BREAKING CHANGE 3 — HasIndex now throws for Cosmos.
            // EF 8 silently ignored it; EF 9 raises InvalidOperationException.
            // The previous .HasIndex(b => b.Name) call has been removed.
        });
    }
}

class Blog { public string Id { get; set; } public string Name { get; set; } }

