using System.Linq;

class SyncJob
{
    void Run(BlogContext context)
    {
        // BREAKING CHANGE 4 — Raw SQL using c.Discriminator must be updated.
        // EF 9 uses "$type" for the discriminator JSON property by default.
        // Since we pinned it to "Discriminator" in OnModelCreating, existing
        // raw SQL like `WHERE c.Discriminator = 'Blog'` continues to work.
        // Without that fix, you'd need: WHERE c["$type"] = 'Blog'

        var blogs = context.Blogs.ToList();
        foreach (var b in blogs) { b.Name = b.Name.Trim(); }
        context.SaveChanges();
    }
}

